--borderC:#e9e9e90d;
--linkBC:#e9e9e90d;
--offCV:#161617;
}
/**
*
* = NORMALIZE
*
* ========================================================================= */
html {
position: relative;
word-wrap: break-word;
-webkit-text-size-adjust: 100%;
-webkit-tap-highlight-color: rgba(0, 0, 0, 0);
}
*,
*::before,
*::after {
box-sizing: border-box;
}
html,body,
div,span,applet,object,iframe,h1,h2,h3,h4,h5,h6,p,blockquote,pre,abbr,acronym,address,big,cite,
code,del,dfn,em,ins,kbd,q,s,samp,small,strike,strong,sub,sup,tt,var,dl,dt,dd,ol,ul,li,fieldset,
form,label,legend,table,caption,tbody,tfoot,thead,tr,th,td {
padding: 0;
margin: 0;
border: 0;
outline: none;
vertical-align: baseline;
background: 0 0;
text-decoration: none;
}
a,
button {
cursor: revert;
text-decoration: none;
}
ol,
ul,
menu {
list-style: none;
padding: 0;
margin: 0;
}
u {
text-decoration: underline;
}
strike {
text-decoration: line-through;
}
b,
strong {
font-weight: 600;
}
img,
iframe {
max-width: 100%;
border-radius: var(--imgRadius);
}
img {
height: auto;
}
a[style*="1em"]:not([style*="clear"]) {
margin: 0 !important;
}
.clear{
clear:both;
}
.quickedit,
.cookie-choices-info {
display:none;
visibility:hidden;
opacity:0
}
/**
*
* = GENERAL
*
* ========================================================================= */
body {
position: relative;
background: var(--bodyB);
color: var(--textC);
font: var(--bodyF);
overflow-x: hidden;
-moz-osx-font-smoothing: grayscale;
-webkit-font-smoothing: antialiased;
}
h1, h2, h3, a {
color: var(--linkC);
}
button, input, select, textarea {
color: var(--linkC);
font-family: var(--titleF);
}
.fa, .far, .fas {
font-family: "Font Awesome 5 Free";
}
.fab{
font-family:"Font Awesome 5 Brands";
}
/* === ARTICLE BODY */
.articleBody {
line-height: 1.8;
}
.articleBody h1,
.articleBody h2,
.articleBody h3 {
margin-top: 1.2em;
margin-bottom: 1em;
}
.articleBody p {
margin-top: .8em;
margin-bottom: .8em;
}
.articleBody ul,
.articleBody ol {
margin: 1.2em 0 1.2em 0;
padding: 0 0 0 40px;
}
.rtl .articleBody ul,
.rtl .articleBody ol {
padding: 0 40px 0 0;
}
.articleBody ul {
list-style: disc;
}
.articleBody ol {
list-style: decimal;
}
/* === BLOCK LOADER */
.loader {
position: relative;
width: 100%;
height: 100%;
display: grid;
grid-template-columns: 1fr 1fr;
grid-gap: 5px;
text-align: center;
align-items: center;
min-height: 280px;
align-content: center;
}
.loader i {
width: 8px;
height: 8px;
border-radius: 100px;
background-color: var(--mainC);
animation: loader 1.2s linear infinite;
}
.loader i:nth-child(1) {
animation-delay: 0s;
margin: 0 0 0 auto;
}
.rtl .loader i:nth-child(1) {
margin: 0 auto 0 0;
}
.loader i:nth-child(2) {
animation-delay: -0.4s;
margin: 0 auto 0 0;
}
.rtl .loader i:nth-child(2) {
margin: 0 0 0 auto;
}
.loader i:nth-child(3) {
animation-delay: -0.8s;
margin: 0 0 0 auto;
}
.rtl .loader i:nth-child(3) {
margin: 0 auto 0 0;
}
.loader i:nth-child(4) {
animation-delay: -0.4s;
margin: 0 auto 0 0;
}
.rtl .loader i:nth-child(4) {
margin: 0 0 0 auto;
}
@keyframes loader {
0%, 100% {opacity: .5;}
50% {opacity: .1;}
}
