}
.layout-1 .grid-8 .posts,
.layout-5 .grid-8 .posts,
.section:not(.canvas-1,.canvas-2) .sided-1 .posts,
.sided-2 .posts,
[data-type="featuredLabel"] .widget-content,
.footer .footer-columns {
