}
.slider-1 .post:not(.wrp-2),
.slider-1_2 .post:not(.wrp-2) {
display: grid;
grid-template-columns: 90px 1fr;
grid-gap: 15px;
}
.slider-1 .post:not(.wrp-2) .postDetails {
